def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    dangerous_bids = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = float(prev['bid'])
                prev_bids.append(bid)
                if opp.get('water_requirement', WATER_REQ) >= WATER_REQ:
                    dangerous_bids.append(bid)

    if not alive_opponents:
        return max(0.0, min(float(budget), 18.0))

    ref_bids = dangerous_bids if dangerous_bids else prev_bids
    highest_prev = max(ref_bids) if ref_bids else 0.0
    avg_prev = sum(ref_bids) / len(ref_bids) if ref_bids else 0.0

    tight_supply = supply <= 18.0
    ample_supply = supply >= 22.0
    critical = hp <= 3 or no_water_days >= 2
    pressured = hp <= 5 or no_water_days >= 1

    if critical:
        bid = highest_prev + 2.5 if highest_prev > 0 else DAILY_SALARY * 1.05
    elif tight_supply:
        if highest_prev >= 95.0:
            bid = highest_prev + 1.5
        else:
            bid = max(78.0, highest_prev + 2.0)
    elif ample_supply:
        if hp >= 8 and no_water_days == 0:
            bid = 26.0
        else:
            bid = 52.0 if avg_prev >= 90.0 else 44.0
    else:
        if pressured:
            bid = max(72.0, highest_prev + 1.0 if highest_prev > 0 else 72.0)
        else:
            bid = 48.0 if avg_prev >= 90.0 else 58.0

    if day >= 8 and hp >= 7 and no_water_days == 0 and not tight_supply:
        bid = min(bid, 40.0)

    if budget < bid:
        if critical:
            bid = budget
        else:
            bid = min(float(budget), max(0.0, budget * 0.75))

    if budget <= 0:
        return 0.0

    return max(0.0, min(float(budget), float(bid)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Extract yesterday bids to infer aggressiveness
    prev_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                prev_bids.append(float(bid))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    # If Cindy was the dominant bidder yesterday, assume she continues to pressure.
    # We don't know who is Cindy, so use the highest previous bid as proxy.
    pressure = 0.0
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        pressure = 1.0
    elif highest_prev_bid >= DAILY_SALARY * 0.55:
        pressure = 0.6
    else:
        pressure = 0.3

    # Decide bid level.
    # Goal: outcompete only when needed; otherwise conserve budget.
    # If I'm in danger (low hp or already no-water days), bid more.
    danger = 0.0
    if hp <= 2.0:
        danger = 1.0
    elif hp <= 4.0:
        danger = 0.7
    elif no_water_days >= 2:
        danger = 0.6
    else:
        danger = 0.3

    # Supply affects how much water is likely to be contested; higher supply reduces need.
    supply_factor = 0.0
    if supply >= 22.0:
        supply_factor = 0.85
    elif supply >= 18.0:
        supply_factor = 1.0
    else:
        supply_factor = 1.15

    # Baseline bid: slightly above moderate range.
    # Use pressure and danger to scale.
    target = DAILY_SALARY * (0.45 + 0.25 * pressure + 0.25 * danger)
    target *= supply_factor

    # If yesterday pressure was extreme, nudge upward to avoid being starved.
    if highest_prev_bid >= DAILY_SALARY * 0.95:
        target = max(target, highest_prev_bid * 0.98)
    elif highest_prev_bid >= DAILY_SALARY * 0.7:
        target = max(target, highest_prev_bid * 0.9)

    # Keep within budget and reasonable cap.
    # Also avoid bidding above what would be wasteful given average supply.
    cap = min(budget, DAILY_SALARY * 1.25)
    bid = max(0.0, min(cap, target))

    # If we are already at/near zero budget, still bid what we can.
    if budget <= 1.0:
        return 0.0

    # Ensure at least a small bid if safe; otherwise conserve.
    if bid < DAILY_SALARY * 0.2 and danger < 0.7:
        bid = min(bid, DAILY_SALARY * 0.2)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    my_hp = my_status['hp']
    my_budget = my_status['budget']
    my_no_water_days = my_status['no_water_days']
    supply = day_context['supply']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    # 1. If no opponents, bid minimally to save budget.
    if num_alive_opponents == 0:
        return min(my_budget, DAILY_SALARY * 0.1)

    # Calculate total water required by all alive agents (including myself)
    total_water_needed_by_players = WATER_REQ
    for opp in alive_opponents:
        total_water_needed_by_players += opp['water_requirement']

    # Determine a base bid multiplier based on supply vs demand
    base_bid_multiplier = 0.55 # Default
    if supply < total_water_needed_by_players:
        # Supply is scarce, increase base bid
        base_bid_multiplier = 0.7
        # Even more scarce, if supply is less than avg water req per player
        if supply < WATER_REQ * (num_alive_opponents + 1) / 2:
             base_bid_multiplier = 0.85
    else:
        # Supply is abundant or sufficient, can try to bid lower
        base_bid_multiplier = 0.45

    current_bid = DAILY_SALARY * base_bid_multiplier

    # Look at yesterday's bids of alive opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    highest_prev_bid = 0.0
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

    # 2. Prioritize survival if HP is critical
    if my_hp <= 2:
        return min(my_budget, DAILY_SALARY * 0.98)

    # 3. If I haven't gotten water recently, increase bid
    if my_no_water_days > 0:
        current_bid = max(current_bid, DAILY_SALARY * 0.9)
        return min(my_budget, current_bid)

    # 4. React to opponent's previous high bids
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        if my_hp > 5:
            current_bid = max(current_bid, highest_prev_bid + 1.0, DAILY_SALARY * 0.75)
        else:
            current_bid = max(current_bid, highest_prev_bid + 1.0, DAILY_SALARY * 0.9)
    elif highest_prev_bid > 0:
        current_bid = max(current_bid, highest_prev_bid + 1.0)

    # Final check and cap
    # If my HP is very good, I can afford to be less aggressive to save budget
    if my_hp > 7 and current_bid > DAILY_SALARY * 0.8:
        current_bid = min(current_bid, DAILY_SALARY * 0.75)

    # Ensure bid doesn't exceed budget
    return min(my_budget, current_bid)

